-- SECURITY DEFINER; API roles that may call it: service_role
CREATE OR REPLACE FUNCTION public.on_event_suggestion()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare a record; nm text;
begin
  select name into nm from public.profiles where id = new.creator_id;
  for a in select id from public.profiles where is_admin and id <> new.creator_id loop
    perform public.notify_user(a.id, 'event', 'Event suggestion',
      coalesce(nm,'A creator') || ' suggested: ' || new.title, '/calendar');
  end loop;
  return new;
end $function$;
